 55→export class PlayerView implements OnInit, OnDestroy {
 56→  protected readonly store = inject(ExerciseStore);
 57→  protected readonly domain = inject(DomainService);
 58→  private readonly api = inject(EngineApiService);
 59→  private readonly decisionApi = inject(DecisionApiService);
 60→  private readonly auditApi = inject(AuditApiService);
 61→  protected readonly logsOpen = signal(false);
 62→  protected readonly auditLog = signal<AuditEntry[]>([]);
 63→  private readonly ws = inject(ExerciseWsService);
 64→  private readonly router = inject(Router);
 65→  private readonly route = inject(ActivatedRoute);
 66→  protected readonly roleLabel = signal("Advisor");
 67→  protected readonly beginningExercise = signal(false);
 68→  private readonly exerciseId = signal(1);
 69→  private readonly participantId = signal("");
 70→  private readonly tick = inject(TickService);
 71→  private snapshotLoaded = false;
 72→  private sub: Subscription | null = null;
 73→  private connSub: Subscription | null = null;
 74→
 75→  protected readonly activeDecisions = computed(() => {
 76→    const role = this.store.playerRole();
 77→    return this.store.openDecisions().filter((d) => {
 78→      if (!d.target_roles || d.target_roles.length === 0) return true;
 79→      if (role === "all_roles" || role === "all_advisors" || role === "solo_player") return true;
 80→      return d.target_roles.includes(role);
 81→    });
 82→  });
 83→
 84→  protected readonly isMultiRole = computed(() => {
 85→    const role = this.store.playerRole();
 86→    return role === "all_advisors" || role === "solo_player" || role === "all_roles";
 87→  });
 88→
 89→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 90→
 91→  protected readonly currentTurnEvent = computed(() => {
 92→    const decisions = this.activeDecisions();
 93→    if (decisions.length === 0) return null;
 94→    const decision = decisions[0];
 95→    if (!decision.event_id) return null;
 96→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
 97→  });
 98→
 99→  protected readonly roleCards = computed(() => {
100→    const allRoles = this.store.context()?.roles ?? [];
101→    const event = this.currentTurnEvent();
102→    const decision = this.activeDecisions()[0] ?? null;
103→    const role = this.store.playerRole();
104→    const multiRole = this.isMultiRole();
105→    const showDecisionMaker =
106→      role === "all_roles" || role === "solo_player" || this.store.isPracticeMode();
107→    // Single-role players see only their own role card
108→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
109→    return buildRoleCards(roles, event, decision, this.submittedRoles(), showDecisionMaker);
110→  });
111→
112→  private _lastDecisionId: string | null = null;
113→  private readonly resetSubmittedRolesEffect = effect(() => {
114→    const id = this.activeDecisions()[0]?.id ?? null;
115→    // Only reset when the decision ID actually changes (not on every WS push)
116→    if (id && id !== this._lastDecisionId) {
117→      this._lastDecisionId = id;
118→      this.submittedRoles.set(new Set());
119→    }
120→  });
121→
122→  /** In practice mode, skip ahead to the next turn as soon as a decision is resolved. */
123→  private _prevHadDecision = false;
124→  private readonly practiceAutoAdvanceEffect = effect(() => {
125→    if (!this.store.isPracticeMode()) return;
126→    if (this.store.phase() !== "running") return;
127→    const hasDecision = this.activeDecisions().length > 0;
128→    // Detect transition from having a decision to having none (= decision just resolved)
129→    if (this._prevHadDecision && !hasDecision) {
130→      const nextEvent = this.store
131→        .scheduledEvents()
132→        .sort((a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms)[0];
133→      if (nextEvent) {
134→        this.api.triggerEvent(this.exerciseId(), nextEvent.id).subscribe();
135→      }
136→    }
137→    this._prevHadDecision = hasDecision;
138→  });
139→
140→  ngOnInit(): void {
141→    const params = this.route.snapshot.queryParams;
142→    const id = Number(params["exerciseId"] ?? 1);
143→    const pId = String(params["participantId"] ?? "");
144→    const role = String(params["role"] ?? "player");
145→    const gameMode = String(params["gameMode"] ?? "");
146→    this.exerciseId.set(id);
147→    this.participantId.set(pId);
148→    this.store.setParticipantId(pId);
149→    this.store.setPlayerRole(role);
150→    if (gameMode) {
151→      this.store.setGameMode(gameMode);
152→    }
153→    const practiceMode = params["practiceMode"] === "true";
154→    this.store.setPracticeMode(practiceMode);
155→    this.ws.connect(id, "player", pId || undefined);
156→    this.sub = this.ws.messages$.subscribe((msg) =>
157→      handlePlayerWsMessage(msg, this.store, () => this.onExerciseStopped()),
158→    );
159→    this.loadSnapshot(id);
160→    this.decisionApi.getContext(id).subscribe({
161→      next: (ctx) =>
162→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
163→      error: () => {},
164→    });
165→    this.decisionApi.getEngineDecisions(id).subscribe({
166→      next: (decisions) => this.store.applyDecisions(decisions),
167→      error: () => {},
168→    });
169→    this.connSub = this.ws.connected$.subscribe((connected) => {
170→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
171→    });
172→    this.tick.start(this.store);
173→  }
174→
175→  private loadSnapshot(exerciseId: number): void {
176→    this.api.snapshot(exerciseId).subscribe({
177→      next: (snap) => {
178→        this.snapshotLoaded = true;
179→        this.store.applySnapshot(snap);
180→      },
181→      error: () => this.store.setError("Failed to load snapshot"),
182→    });
183→    this.auditApi.getLog(exerciseId).subscribe({
184→      next: (log) => this.auditLog.set(log),
185→      error: (e) => console.warn("Failed to fetch audit log", e),
186→    });
187→  }
188→
189→  protected onBeginExercise(): void {
190→    this.beginningExercise.set(true);
191→    this.api.begin(this.exerciseId()).subscribe({
192→      next: (change) => {
193→        this.store.applyPhaseChange(change.phase);
194→        this.store.applyTimeUpdate(change.time);
195→        this.beginningExercise.set(false);
196→      },
197→      error: () => {
198→        this.store.setError("Failed to begin exercise");
199→        this.beginningExercise.set(false);
200→      },
201→    });
202→  }
203→
204→  protected onStop(): void {
205→    this.api.stop(this.exerciseId()).subscribe({
206→      next: () => this.onExerciseStopped(),
207→    });
208→  }
209→
210→  private onExerciseStopped(): void {
211→    this.ws.disconnect();
212→    this.router.navigate(["/"]);
213→  }
214→
215→  ngOnDestroy(): void {
216→    this.tick.stop();
217→    this.ws.disconnect();
218→    this.sub?.unsubscribe();
219→    this.connSub?.unsubscribe();
220→  }
221→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
222→    const decision = this.activeDecisions()[0];
223→    if (!decision) return;
224→    const role = this.store.context()?.roles?.find(
225→      (r) => r.id === submission.roleId,
226→    );
227→    if (role?.player_type === "decision_maker") {
228→      submitDecision(
229→        this.decisionApi,
230→        this.store,
231→        this.exerciseId(),
232→        decision,
233→        this.participantId(),
234→        submission,
235→      );
236→    } else {
237→      submitRoleRecommendation(
238→        this.decisionApi,
239→        this.exerciseId(),
240→        decision,
241→        this.participantId(),
242→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
243→      );
244→    }
245→    const updated = new Set(this.submittedRoles());
246→    updated.add(submission.roleId);
247→    this.submittedRoles.set(updated);
248→  }
249→}
