102→export class RoleCardComponent {
103→  readonly card = input.required<RoleCard>();
104→  readonly submitted = output<RoleCardSubmission>();
105→
106→  readonly selectedOptions = signal<string[]>([]);
107→  readonly freeText = signal("");
108→
109→  private readonly resetOnCardChange = effect(() => {
110→    this.card();
111→    untracked(() => {
112→      this.selectedOptions.set([]);
113→      this.freeText.set("");
114→    });
115→  });
116→
117→  readonly filteredOptions = computed<DecisionOption[]>(() => {
118→    const decision = this.card().decision;
119→    if (!decision) return [];
120→    const playerType = this.card().playerType;
121→    const roleId = this.card().roleId;
122→    if (playerType === "decision_maker") {
123→      return decision.options;
124→    }
125→    // advisor: COMMON options (no role) + own-role options
126→    return decision.options.filter(
127→      (o) => !o.role || o.role === roleId,
128→    );
129→  });
130→
131→  readonly badgeLabel = computed<string>(() => {
132→    const status = this.card().status;
133→    if (status === "intel") return "INTEL";
134→    if (status === "active") return "DECISION";
135→    return "DONE";
136→  });
137→
138→  readonly questionType = computed<string>(() => {
139→    return this.card().decision?.question_type ?? "free_text";
140→  });
141→
142→  readonly doneLabel = computed<string>(() => {
143→    const decision = this.card().decision;
144→    if (!decision) return "";
145→    const roleId = this.card().roleId;
146→    const recEntry = Object.entries(decision.recommendations).find(
147→      ([key]) => extractRecRoleId(key) === roleId,
148→    );
149→    const optionId = recEntry?.[1];
150→    if (!optionId) return "";

  ]
},
